-- ==== db/migrations/0055_20260812_release_authorization.sql =======================================
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- 0055 · PHASE 11-F — owner-liveness delivery, the two-person release rule, and the release record
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ WHAT THE FIVE APPROVED DECISIONS CHANGE, AND WHY EACH NEEDS SCHEMA.
--
-- D1 · TWO-PERSON RULE. The operator who verifies a death may not be the operator who authorizes
--      release, and that is enforced in the DATABASE, not in a console. `release_authorizations`
--      records both reviewers as first-class columns with a CHECK that they differ — so the rule
--      survives a UI rewrite, a direct RPC call, and a future admin tool nobody has written yet.
--
-- D2 · THE CLOCK STARTS AT DISPATCH, NOT AT VERIFICATION. A seventh lifecycle state
--      (`owner_notification_dispatched`) sits between `death_verified` and `challenge_window`
--      precisely so "we accepted the death" and "we told the owner" cannot be the same fact. The
--      duration is 7 x 24h — now an approved decision, so 0055 SEEDS it (0054 deliberately did not,
--      because in 11-E it was not yet decided).
--
-- D4 · IN-APP ALONE IS INSUFFICIENT. `owner_notice_outbox` is the independently-reachable channel:
--      an email row committed in the same transaction as the dispatch transition. The requirement is
--      DISPATCH INITIATION — the row exists and is addressed — never a read receipt, an open, or an
--      acknowledgement, none of which the product can honestly observe.
--
-- ★ WHAT THIS MIGRATION STILL CANNOT DO. It creates no grant, tier, membership or designation, and
-- it makes `released` no easier to reach: the route is still `challenge_window -> released` alone,
-- now additionally gated on two distinct reviewers and a dispatched notice (D5).
--
-- IDEMPOTENT. Safe to re-apply. APPLY ORDER: after 0054, inside the bundles that carry it.

-- [psql meta-command removed for the SQL editor] \set ON_ERROR_STOP on

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 1 · THE SEVENTH LIFECYCLE STATE — "we told the owner" is its own fact
-- ────────────────────────────────────────────────────────────────────────────────────────────────
do $$
declare v_name text;
begin
  for v_name in
    select con.conname
      from pg_constraint con
      join pg_class rel on rel.oid = con.conrelid
      join pg_namespace nsp on nsp.oid = rel.relnamespace
     where nsp.nspname = 'public' and rel.relname = 'estate_lifecycle'
       and con.contype = 'c' and pg_get_constraintdef(con.oid) ilike '%state%'
  loop
    execute format('alter table public.estate_lifecycle drop constraint %I', v_name);
  end loop;

  alter table public.estate_lifecycle
    add constraint estate_lifecycle_state_check
    check (state in (
      'active',
      'death_verification_pending',
      'death_verified',
      -- Phase 11-F (D2): the owner has been told, and the challenge clock has started.
      'owner_notification_dispatched',
      'challenge_window',
      'challenge_halted',
      'released'
    ));
end $$;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 2 · THE OWNER NOTICE OUTBOX — the independently reachable channel (D4)
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ A SEPARATE TABLE FROM `invitation_delivery_outbox`, DELIBERATELY. That outbox is FK-bound to an
-- invitation and drained by a daily cron whose claim predicate has no age bound — the right class
-- for an invitation email and the wrong one for the notice that starts a release clock. Sharing it
-- would silently inherit both properties.
--
-- ★ THE RECIPIENT IS RESOLVED AND STORED AT DISPATCH. Storing the address is what makes
-- "independently reachable" a checkable fact rather than an assumption: a dispatch with no
-- resolvable address must FAIL, not queue a row nobody can deliver.
create table if not exists public.owner_notice_outbox (
  id            uuid        primary key default gen_random_uuid(),
  estate_id     uuid        not null references public.estates(id) on delete cascade,
  user_id       uuid        not null references auth.users(id),
  -- Email is the minimum bar (D4). Push, when it exists, is SUPPLEMENTAL and joins this CHECK by a
  -- reviewed migration — it never replaces the email row.
  channel       text        not null default 'email' check (channel in ('email')),
  recipient     text        not null,
  notice_kind   text        not null check (notice_kind in ('death_process.window_opened')),
  status        text        not null default 'queued'
    check (status in ('queued', 'processing', 'dispatched', 'failedPermanent', 'cancelled')),
  requested_at  timestamptz not null default now(),
  dispatched_at timestamptz,
  attempts      int         not null default 0,
  next_attempt_at timestamptz,
  failure_class text,
  purge_audit_id uuid
);

create index if not exists owner_notice_outbox_estate_idx on public.owner_notice_outbox (estate_id);
create index if not exists owner_notice_outbox_claimable_idx
  on public.owner_notice_outbox (requested_at) where status in ('queued', 'processing');

alter table public.owner_notice_outbox enable row level security;
-- ZERO grants, ZERO policies: a row here names a living owner's email address and the fact that a
-- death process is running against their estate. Only DEFINER routines may touch it.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 3 · THE RELEASE AUTHORIZATION RECORD — its own model, never overloaded (Stage 5)
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ NOT A CLAIM PACKET, NOT A MEMBERSHIP, NOT A DESIGNATION. Each of those answers a different
-- question with a different actor, evidence and reversibility; overloading one of them to carry
-- "two operators authorized this release" is how a fact acquires the wrong lifecycle. This table
-- exists so the release event has a home with exactly the fields the audit needs.
--
-- ★ THE TWO-PERSON RULE IS A TABLE CONSTRAINT (D1). Not a trigger, not a routine-only check: a CHECK
-- means no INSERT anywhere — routine, migration, console, future admin tool — can record a release
-- authorized by one person. The routine enforces it too; this is the layer that cannot be bypassed.
create table if not exists public.release_authorizations (
  id            uuid        primary key default gen_random_uuid(),
  estate_id     uuid        not null references public.estates(id) on delete cascade,
  case_id       uuid        not null references public.death_verification_cases(id),
  -- reviewer_a VERIFIED THE DEATH. reviewer_b AUTHORIZED THE RELEASE. They must differ.
  reviewer_a    uuid        not null references auth.users(id),
  reviewer_b    uuid        not null references auth.users(id),
  verified_at   timestamptz not null,
  authorized_at timestamptz not null default now(),
  released_at   timestamptz,
  audit_reason  text        not null,
  constraint release_authorizations_two_person check (reviewer_a <> reviewer_b)
);

-- One authorization per estate: release is not a thing that happens twice.
create unique index if not exists release_authorizations_one_per_estate
  on public.release_authorizations (estate_id);

alter table public.release_authorizations enable row level security;
-- ZERO grants, ZERO policies — DEFINER-routine-only, like every other record on this path.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 4 · THE PURGE AUDIT — nothing is ever silently deleted (Stage 3)
-- ────────────────────────────────────────────────────────────────────────────────────────────────
create table if not exists public.outbox_purge_audit (
  id            uuid        primary key default gen_random_uuid(),
  outbox_name   text        not null,
  purged_at     timestamptz not null default now(),
  actor_id      uuid,
  row_count     int         not null,
  oldest_row_at timestamptz,
  newest_row_at timestamptz,
  reason        text        not null
);
alter table public.outbox_purge_audit enable row level security;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 5 · THE CHALLENGE WINDOW DURATION — 7 x 24h, now an APPROVED decision (D2)
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ 0054 DELIBERATELY SEEDED NOTHING, AND THAT WAS RIGHT THEN. In 11-E the duration was undecided,
-- so the fail-closed posture was "no window can ever elapse". D2 decides it, so it is recorded here
-- — in a migration, reviewably, once — rather than left to an operator's console session where
-- nobody could later say what value production carries or when it changed.
--
-- `on conflict do update` is deliberate: re-applying this migration re-asserts the approved value,
-- so a hand-edited production row is corrected by the next paste rather than silently kept.
insert into public.release_safety_policy (id, challenge_window)
values (true, interval '7 days')
on conflict (id) do update set challenge_window = excluded.challenge_window, updated_at = now();

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 6 · REMOVE the one-person release lever
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE 0053 PRECEDENT, APPLIED TO AN ACTOR RATHER THAN AN ARGUMENT. 11-E's `release_estate(uuid)`
-- had no concept of a second reviewer. Leaving it in place beside the two-person door would be a
-- second release path that bypasses D1 entirely — and `create or replace` cannot remove it, because
-- the replacement has a different name and signature. It is DROPPED, so a caller that was never
-- rewired fails loudly instead of releasing on one person's say-so.
drop function if exists public.release_estate(uuid);

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- 7 · PROVE IT TOOK, IN THE MIGRATION ITSELF (both directions)
-- ────────────────────────────────────────────────────────────────────────────────────────────────
do $$
declare v_def text; v_n int;
begin
  select pg_get_constraintdef(con.oid) into v_def
    from pg_constraint con
    join pg_class rel on rel.oid = con.conrelid
    join pg_namespace nsp on nsp.oid = rel.relnamespace
   where nsp.nspname = 'public' and rel.relname = 'estate_lifecycle'
     and con.contype = 'c' and pg_get_constraintdef(con.oid) ilike '%state%';
  if v_def is null or position('owner_notification_dispatched' in v_def) = 0 then
    raise exception '0055 FAILED: the dispatch state is not storable: %', coalesce(v_def, '<absent>');
  end if;
  if (select count(*) from regexp_matches(v_def, '''[a-z_]+''', 'g')) <> 7 then
    raise exception '0055 FAILED: the lifecycle vocabulary is not exactly seven states: %', v_def;
  end if;

  -- The two-person CHECK must exist as a CONSTRAINT, not merely as routine logic.
  if not exists (
    select 1 from pg_constraint where conname = 'release_authorizations_two_person'
  ) then
    raise exception '0055 FAILED: the two-person rule is not a table constraint — routine-only '
      'enforcement can be bypassed by any other writer';
  end if;
  -- …and it must actually refuse. Proven, not assumed.
  begin
    insert into public.release_authorizations
      (estate_id, case_id, reviewer_a, reviewer_b, verified_at, audit_reason)
    select e.id, c.id, c.initiated_by, c.initiated_by, now(), '0055 self-check'
      from public.estates e join public.death_verification_cases c on c.estate_id = e.id limit 1;
    -- If a row existed to try with AND the insert succeeded, the constraint is not working.
    get diagnostics v_n = row_count;
    if v_n > 0 then
      raise exception '0055 FAILED: a single-reviewer release authorization was insertable';
    end if;
  exception when check_violation then
    null; -- the constraint refused, which is the point
  end;

  -- ★ THE TABLE, NOT THE READER. `challenge_window_duration()` lives in `release_safety.sql`, which
  -- ships in a LATER bundle — so a migration that asked the function would raise on the first paste
  -- of the release-conditions bundle, where 0055 legitimately runs before that function exists. A
  -- migration must be checkable against the schema it changed, not against a function some other
  -- artifact happens to carry.
  if (select p.challenge_window from public.release_safety_policy p where p.id)
     is distinct from interval '7 days' then
    raise exception '0055 FAILED: the challenge window is % (expected 7 days per D2)',
      (select p.challenge_window from public.release_safety_policy p where p.id);
  end if;

  if to_regprocedure('public.release_estate(uuid)') is not null then
    raise exception '0055 FAILED: the one-person release lever still exists — D1 would be bypassable';
  end if;

  if exists (
    select 1 from information_schema.role_table_grants
     where table_schema = 'public'
       and table_name in ('owner_notice_outbox', 'release_authorizations', 'outbox_purge_audit')
       and grantee in ('anon', 'authenticated')
  ) then
    raise exception '0055 FAILED: a client role holds a grant on a release-path table';
  end if;

  raise notice '0055 · release authorization in place (7 lifecycle states; owner notice outbox; '
    'two-person CHECK enforced; window = 7 days; one-person lever dropped)';
end $$;


-- ==== db/functions/release_conditions.sql =========================================================
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- THE CANONICAL RELEASE-CONDITION AUTHORITY  ·  Phase 11-B, lifecycle-aware since Phase 11-D
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- ★ WHY THIS FILE EXISTS. Before Phase 11-B the rule "is this grant's release condition satisfied?"
-- was written out SEVEN times in FIVE routines, and the seven copies gave TWO different answers:
--
--     can_access_document          immediately + the two approval conditions once approved
--     inventory_disclosure_tier    same
--     notification_grant_is_live   same
--     asset_grant_tier             immediately ONLY
--     list_estate_assets           immediately ONLY
--     get_estate_net_worth  (×2)   immediately ONLY
--
-- Phase 11 connects a verified death to disclosure. The single most likely way to get that wrong is
-- not a missing check — it is activating a condition at four sites and forgetting the other three,
-- which is precisely the shape of the four role maps that drifted apart in Phase 9. So the predicate
-- moved HERE first (11-B), before any death wiring existed, and every consumer became a caller.
--
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- ★ WHAT THIS MODULE DECIDES, AND WHAT IT DELIBERATELY DOES NOT
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- It answers ONE question: given a release condition, the approval fact recorded beside it, and the
-- estate's authoritative lifecycle state, is that condition presently SATISFIED?
--
-- It does NOT decide who may receive a grant, compute a disclosure tier, manufacture a grant, verify
-- a death, approve a claim, or transition any lifecycle state. Callers keep every one of those. A
-- grant whose condition is satisfied still discloses nothing unless the SAME checks that have always
-- guarded it also pass: active status, the viewer's own grant row, the read-time ceiling clamp, the
-- hidden-tier refusal. Satisfaction is one conjunct, never a bypass.
--
-- ★ IT TAKES LIFECYCLE STATE AS AN ARGUMENT, AND READS NOTHING — THAT IS THE 11-D DESIGN.
--
-- 11-B deliberately gave this function no lifecycle argument, so that "no authorization path
-- consults the release seam" stayed structurally true while there was no verified event to consult.
-- 11-D is the phase that spends that guarantee, deliberately, in ONE file: the signature widens to
--
--     release_condition_satisfied(condition, approved_at, policy, lifecycle_state)
--
-- and every consumer resolves the lifecycle through `public.estate_lifecycle_state(estate)` — the
-- authoritative reader over `estate_lifecycle`, the record whose ONLY writer is the audited
-- transition routine. The predicate itself stays a PURE function of its arguments (immutable, no
-- table reads), for three reasons:
--
--   · a pure predicate can be truth-tabled exhaustively against a written specification, which is
--     how the SQL suite proves it (every condition × approval × policy × lifecycle, enumerated);
--   · a predicate that resolved estate → lifecycle itself would be a client-reachable death-status
--     oracle for arbitrary estate ids (it is EXECUTEable by `authenticated`; the reader is not);
--   · the lifecycle READ stays in SECURITY DEFINER consumers beside the grant lookup it scopes, so
--     the estate whose lifecycle is consulted is by construction the estate whose grant is evaluated.
--
-- What no consumer may do is compare the lifecycle locally ("if death_verified then …") — that is
-- release policy leaking back out of the centre, and `test/deathVerificationFoundation.test.ts`
-- pins that the reader appears outside the death module ONLY as this function's fourth argument.
--
-- ★ NOT `claim_packets.status`. NOT evidence rows. NOT attained verification levels. NOT the
-- label-only `estate_release_state()` claim projection. The lifecycle record is the one fact that
-- can satisfy a death condition, and it moves only through `apply_estate_lifecycle_transition`,
-- behind an admin decision that re-derives the required verification level LIVE (H2).
--
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- ★ TWO POLICIES, STILL — 11-D activates death under `standard` and PRESERVES the legacy clamp
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- `standard` (documents, the estate-documents category, estate inventory, notification speech):
-- gains the death arm. `after_verified_death` is satisfied exactly while the lifecycle is
-- `death_verified`.
--
-- `legacy_immediate_only` (account balances, institution names, total asset value, linked account
-- details): carried forward EXACTLY as written — `immediately` alone, lifecycle-indifferent. A
-- death-conditioned grant on an asset-value surface therefore stays dormant even at death_verified.
-- That asymmetry is deliberate and is pinned by test in both directions: unifying the policies
-- changes what a survivor sees on the asset surfaces, which is a product decision with its own row
-- inventory and migration price (R12), not a tidy-up. The divergence remains one `case` arm in one
-- file instead of seven scattered literals.
--
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- ★ FAIL-CLOSED IN EVERY ARGUMENT
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- An unknown condition is false. An unknown policy is false. An unknown or NULL lifecycle state is
-- false — for EVERY condition, including `immediately`: the authoritative reader can only produce
-- the three CHECK-constrained states, so an out-of-vocabulary lifecycle here means a consumer wired
-- something that is not the seam, and the answer to a miswired consumer is refusal, not tolerance.
-- NULL condition and NULL policy are false. There is no permissive default and no `else true`
-- anywhere below.
--
-- The `coalesce` is load-bearing rather than defensive tidiness: `null = 'immediately'` is NULL, not
-- false, and a boolean gate that returns NULL is not refused by `if not (…) then` — that branch
-- simply does not execute, and the caller carries on as though the check had passed. A three-valued
-- answer from a two-valued gate is how a fail-closed predicate fails open.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- release_condition_satisfied(condition, approved_at, policy, lifecycle_state) — THE AUTHORITY
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- `p_policy` has NO DEFAULT, on purpose. A default would let a new consumer inherit the wider rule by
-- saying nothing, which is the exact failure mode — silent policy by omission — that the seven
-- scattered copies represented. `p_lifecycle_state` has no default for the same reason: a consumer
-- that says nothing about the lifecycle must not silently evaluate "as if active"; it must not
-- compile. (The 3-argument spelling is DROPPED by migration 0053, so an un-rewired caller fails
-- loudly at first call rather than binding to a lifecycle-blind overload.)
create or replace function public.release_condition_satisfied(
  p_release_condition text,
  p_approved_at       timestamptz,
  p_policy            text,
  p_lifecycle_state   text
)
 returns boolean
 language sql
 immutable
 set search_path to 'public'
as $function$
  select coalesce(
    -- ★ THE LIFECYCLE VALIDITY GATE COMES FIRST and refuses EVERYTHING on an out-of-vocabulary
    -- state. The set is the deployed CHECK's (0052 widened by 0054), spelled here because a pure
    -- function cannot read the catalog; `db/tests/release_condition_authorization.sql` enumerates
    -- the CHECK at run time and fails if the two vocabularies ever drift.
    -- ★ THE GATE MUST NAME EVERY STORABLE STATE, INCLUDING ONES THAT SATISFY NOTHING. A state
    -- missing here refuses EVERY condition for that estate — including `immediately` — so an
    -- owner's ordinary live grants would go dark the moment a death process reached the unlisted
    -- state. Failing closed on an UNKNOWN state is the design; failing closed on a KNOWN one is a
    -- disclosure outage. 11-F's `owner_notification_dispatched` joins the list for that reason and
    -- for no other: it satisfies nothing, exactly like the two states either side of it.
    p_lifecycle_state in ('active', 'death_verification_pending', 'death_verified',
                          'owner_notification_dispatched',
                          'challenge_window', 'challenge_halted', 'released')
    and case p_policy
      -- Documents, the estate-documents category, estate inventory, and notification speech.
      -- `after_owner_approval` (owner-initiated) and `after_access_request_approval`
      -- (beneficiary-initiated) are the SAME gate — both mean "the owner approved this access",
      -- differing only by who asked.
      when 'standard' then
        p_release_condition = 'immediately'
        or (p_release_condition in ('after_owner_approval', 'after_access_request_approval')
            and p_approved_at is not null)
        -- ★ THE DEATH ARM — RE-POINTED IN PHASE 11-E (R7). 11-D satisfied this at death_verified;
        -- that connected an accepted verification DIRECTLY to irreversible disclosure, and 11-E
        -- inserts the safety seam: the condition is satisfied ONLY at `released`, which is
        -- reachable only through the challenge window — owner notified in the same transaction,
        -- configured duration strictly elapsed, no owner challenge. death_verified satisfies
        -- NOTHING; challenge_window satisfies NOTHING; challenge_halted satisfies NOTHING.
        -- Claim approval, evidence, and attained levels never appear here because they cannot
        -- move the lifecycle. Incapacity and the legacy fused value stay out of this arm
        -- entirely — dormant under every policy, every lifecycle (R8/R9).
        or (p_release_condition = 'after_verified_death'
            and p_lifecycle_state = 'released')

      -- The asset-value surfaces (account balances, institution names, total asset value, linked
      -- account details). Carried forward EXACTLY as written in 11-B, including their narrowness
      -- and their lifecycle-indifference: `immediately` alone, at every lifecycle state. This is a
      -- compatibility clamp with a standing ledger entry (R12), not a rule anyone designed — and
      -- 11-D deliberately does NOT spend that product decision.
      when 'legacy_immediate_only' then
        p_release_condition = 'immediately'

      -- Unknown policy -> refused. No `else true`, ever.
      else false
    end,
    false);
$function$;

comment on function public.release_condition_satisfied(text, timestamptz, text, text) is
  'THE canonical release-condition authority (Phase 11-B; lifecycle-aware since 11-D; safety-seamed '
  'in 11-E). Answers only "is this condition presently satisfied", never who may receive a grant, '
  'what tier they get, or whether anyone has died. PURE: the lifecycle arrives as an argument, '
  'resolved by SECURITY DEFINER consumers through public.estate_lifecycle_state — never from claim '
  'status, evidence, or attained levels. after_verified_death is satisfied only under the standard '
  'policy at RELEASED (R7) — death_verified, challenge_window and challenge_halted all satisfy '
  'nothing; incapacity, the legacy fused value, identity and claim conditions are dormant under '
  'every policy. Unknown condition, unknown policy, unknown lifecycle and NULL all refuse.';

revoke execute on function public.release_condition_satisfied(text, timestamptz, text, text) from public, anon;
grant  execute on function public.release_condition_satisfied(text, timestamptz, text, text) to authenticated;

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- release_condition_writable(condition) -> boolean   — THE WRITE-TIME VOCABULARY GATE
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ THE DEATH/INCAPACITY SPLIT LIVES HERE, AND IT IS A WRITE-SIDE RULE ONLY.
--
-- `after_verified_death_or_incapacity` fused two legally distinct events into one storable value.
-- Death and incapacity differ in who is alive to contest, what evidence exists, whether the owner's
-- own instructions still govern, and whether the change is reversible. A single condition cannot
-- carry both and mean anything.
--
-- The split is done WITHOUT touching stored rows:
--
--   · the table CHECK still ACCEPTS the fused value, so every existing row remains readable and no
--     migration has to guess what an owner meant when they chose it;
--   · this gate REFUSES it for new writes, so no further row can be created carrying the ambiguity;
--   · the satisfied-predicate above treats it as dormant — exactly as it was before — so a legacy
--     row is no more permissive than it was yesterday and no less.
--
-- ★ THE LEGACY VALUE IS NOT REINTERPRETED, AND 11-D DID NOT CHANGE THAT. Now that a verified death
-- can activate `after_verified_death`, the pull to "complete the migration" by mapping fused rows
-- onto the death condition is stronger than ever — and it is still a guess about owner intent that
-- silently makes a stored grant activate on an event the owner may never have chosen alone. Mapping
-- them to `after_verified_incapacity` is the same guess pointing the other way. Both are product
-- decisions about somebody else's estate. An explicit unsatisfiable legacy state costs a
-- re-authoring; a wrong guess costs a disclosure that cannot be undone.
--
-- ★ WRITABLE IS NOT LIVE. `after_verified_death` being writable (11-B) and satisfiable (11-D) are
-- separate facts; `after_verified_incapacity` remains writable and satisfied by NOTHING — nothing
-- verifies an incapacity, and the predicate admits it under no policy. This gate widens what an
-- owner may EXPRESS, never what anybody may SEE.
create or replace function public.release_condition_writable(p_release_condition text)
 returns boolean
 language sql
 immutable
 set search_path to 'public'
as $function$
  select coalesce(p_release_condition in (
    'never',
    'immediately',
    'after_owner_approval',
    'after_identity_verification',
    'after_access_request_approval',
    -- Phase 11-B: the split. Storable and expressible; death satisfiable only since 11-D and only
    -- at death_verified under the standard policy; incapacity satisfied by nothing.
    'after_verified_death',
    'after_verified_incapacity',
    'after_claim_case_approval'
    -- 'after_verified_death_or_incapacity' is DELIBERATELY ABSENT — readable, never writable again.
  ), false);
$function$;

comment on function public.release_condition_writable(text) is
  'Write-time vocabulary gate for access_grants.release_condition (Phase 11-B). Accepts the split '
  'after_verified_death / after_verified_incapacity and REFUSES the deprecated fused '
  'after_verified_death_or_incapacity, which remains legal in the CHECK so stored rows stay readable '
  'and unreinterpreted. Writable is not live: incapacity is satisfied by no policy, and death only '
  'by the authoritative death_verified lifecycle under the standard policy (11-D).';

revoke execute on function public.release_condition_writable(text) from public, anon;
grant  execute on function public.release_condition_writable(text) to authenticated;


-- ==== db/functions/emit_notification.sql ==========================================================
-- public.emit_notification(p_user_id, p_estate_id, p_category, p_title, p_body,
--                          p_deep_link default null, p_payload default '{}') -> uuid (the new id)
--
-- The ONLY way a notification row is created — the anti-forge boundary. SECURITY DEFINER so it
-- bypasses the notifications RLS + the missing INSERT grant (authenticated cannot insert), while a
-- client calling it directly can still only create a notification (it can't read others' — that's
-- RLS on SELECT). Event sources call this as a BEST-EFFORT side effect: the CALLER wraps it in a
-- begin/exception block so a notification failure NEVER fails the load-bearing event (a grant, a
-- request, ...). Kept intentionally generic (any category/title/body) so new emitters reuse it
-- without new plumbing.
--
-- Source of truth — re-apply on DB reset.

create or replace function public.emit_notification(
  p_user_id uuid,
  p_estate_id uuid,
  p_category text,
  p_title text,
  p_body text,
  p_deep_link text default null,
  p_payload jsonb default '{}'::jsonb
)
 returns uuid
 language plpgsql
 volatile
 security definer
 set search_path to 'public'
as $function$
declare
  v_id uuid;
begin
  -- Writes the RECONCILED live schema: the logical category maps to the existing `kind` column, and
  -- `read` (boolean) starts false (unread). See 0009_20260702_notifications.sql.
  insert into public.notifications
    (user_id, estate_id, kind, title, body, channel, action_deep_link, payload, read)
  values
    (p_user_id, p_estate_id, p_category, p_title, p_body, 'inApp', p_deep_link, coalesce(p_payload, '{}'::jsonb), false)
  returning id into v_id;
  return v_id;
end;
$function$;


-- ==== db/functions/lifecycle_notification_rpcs.sql ================================================
-- Phase 10-E — LIFECYCLE NOTIFICATIONS: the emission spine.
--
-- A notification answers exactly one question: *what meaningful thing happened that I was ALREADY
-- authorized to know about?* It is never a second disclosure channel, and every design decision
-- below exists to make that structurally true rather than reviewed case by case.
--
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- ★ THE GOVERNING RULE: NOTIFICATION COPY IS A CONSTANT, LOOKED UP BY EVENT NAME.
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- No emitter composes text. No emitter interpolates. `notification_event_copy` is an IMMUTABLE
-- closed catalog keyed by an event name, and `emit_lifecycle_notification` is the ONLY way a
-- lifecycle row is written.
--
-- This is not stylistic. It is the cheapest correct answer to a whole family of leaks at once:
--
--   · WITHHOLDING IS A PROPERTY OF INFORMATION, NOT OF FIELDS. A body that concatenates anything —
--     a category, a document title, an asset name, a count, an email — is a disclosure decision
--     taken at a call site, by whoever was editing that function that day. Copy that cannot vary
--     cannot leak, and needs no reviewer to notice.
--
--   · IT IS ALREADY PROVEN NECESSARY HERE. The one lifecycle notification in production reads
--     "You've been granted access to estate assets (estate_inventory)." — a raw backend enum,
--     rendered verbatim on a real device, produced by exactly this kind of `||` in a call site.
--     The mobile client has an audit forbidding backend vocabulary on screen; it never fired,
--     because the enum arrived as server-authored prose.
--
--   · REVOCATION SEMANTICS FALL OUT FOR FREE. A revoke notification that names the document whose
--     title is no longer authorized re-discloses it forever, in a row that outlives the grant.
--     Constant copy has nothing to retain, so there is no transition to get wrong.
--
--   · AND IT IS MECHANICALLY AUDITABLE. `db/tests/lifecycle_notification_authorization.sql` asserts
--     that no emitter passes a computed title or body, which a prose rule could never enforce.
--
-- Naming an ESTATE is also refused. The row keeps `estate_id` for provenance — the client already
-- drops it at normalization and never scopes by it — but no copy says which estate, because a
-- person's relationship to an estate is exactly the kind of fact that varies by viewer.
--
-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- ★ WHAT THIS FILE DOES NOT DO, DELIBERATELY.
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- No death activation. No "the estate has been released". No "new assets are available". A
-- death-conditioned grant is DORMANT, and an APPROVED claim releases nothing — so neither may
-- produce a notification that implies otherwise. `notification_grant_is_live` is where that is
-- enforced, and it is enforced by refusing to emit at all rather than by softening the words.

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- The event catalog. Adding an event means adding a row HERE, which is the only place copy exists.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ EVERY STRING IS PURE ASCII, AND THAT IS A REQUIREMENT RATHER THAN AN ACCIDENT. Copy containing
-- a typographic apostrophe cannot be extracted from a Hermes bundle in any tested encoding, so
-- "You've" would be invisible to the mobile bundle audit and its absence would prove nothing. The
-- apostrophes below are deliberately avoided by rephrasing, never by using a curly one.
--
-- ★ THE COPY DESCRIBES IMPACT, AND ONLY IMPACT THAT IS TRUE FOR THAT VIEWER. It never states a
-- capability the viewer may not have ("you can now add documents" tells a beneficiary that an
-- add-document capability exists on this estate), never diagnoses, and never claims delivery,
-- receipt or that anyone read anything.
--
-- ★ AND IT IS JURISDICTION-NEUTRAL. No "probate", no "legal representative", no "court approved",
-- no "estate settled" — none of which the data proves.
create or replace function public.notification_event_copy(p_event text)
 returns table (category text, title text, body text)
 language sql
 immutable
 set search_path to 'public'
as $function$
  select c.category, c.title, c.body
  from (values
    -- ── access requests ───────────────────────────────────────────────────────────────────────
    -- To the OWNER. Says a member requested access; says nothing about WHICH member, because the
    -- brief's own example ("A professional delegate requested access") would make copy vary by
    -- role, and role-varying copy is interpolation wearing a switch statement.
    ('access_request.created',  'accessRequest',  'Access request received',
     'A member of this estate requested access.'),
    -- To the REQUESTER, about their OWN request. Their own outcome is always theirs to know.
    ('access_request.approved', 'accessGranted',  'Access request approved',
     'Your request for access was approved.'),
    ('access_request.denied',   'accessRequest',  'Access request decided',
     'Your request for access was not approved.'),

    -- ── grants ────────────────────────────────────────────────────────────────────────────────
    -- To the GRANTEE, and only for a grant that is LIVE RIGHT NOW — see notification_grant_is_live.
    ('access_grant.created',    'accessGranted',  'Access granted',
     'You have access to shared estate information.'),
    -- ★ THE REVOKE COPY NAMES NOTHING. Not the document, not the category, not the tier. Whatever
    -- was authorized a moment ago may not be authorized now, and a notification row outlives the
    -- grant it describes.
    ('access_grant.revoked',    'accessChanged',  'Access updated',
     'Your access to shared estate information has changed.'),

    -- ── invitations ───────────────────────────────────────────────────────────────────────────
    -- To the OWNER, who issued the invitation and therefore already knows the invitee. This says
    -- LESS than the owner knows, which is the correct direction to err.
    ('invitation.accepted',     'invitationUpdate', 'Invitation accepted',
     'Someone you invited has joined this estate.'),
    ('invitation.declined',     'invitationUpdate', 'Invitation declined',
     'An invitation to this estate was declined.'),

    -- ── the owner safety notice (Phase 11-E) ────────────────────────────────────────────────────
    -- To the OWNER, and ONLY the owner, when the challenge window opens on their estate. The copy
    -- uses exactly the epistemically honest claims the 11-E brief sanctions: a process is waiting,
    -- and the owner can halt it. It asserts no death, names no claimant, no evidence, no deadline
    -- arithmetic, and no estate name. Emitted by begin_challenge_window, which REQUIRES this row
    -- to commit before the window may open — the one notification in the product that is
    -- load-bearing rather than a heads-up.
    ('death_process.window_opened', 'safetyNotice', 'A release process is waiting',
     'A release process is waiting on your estate. You can review and halt it now.'),

    -- ── the halt, to the INITIATING FIDUCIARY (Phase 11-L) ──────────────────────────────────────
    -- To the executor or trustee who OPENED the case, and to nobody else. It tells them one fact
    -- about their OWN action — the same posture as `access_request.denied`, which tells a requester
    -- their own outcome without explaining the decision.
    --
    -- ★ THE VOICE IS PASSIVE ON PURPOSE. "has been halted", never "the owner halted it". Naming the
    -- owner as the actor would disclose that the owner is alive and responded, which is a fact about
    -- a living person's liveness on a channel the recipient has no authority over. The recipient
    -- needs to know their process stopped; they do not need to know who stopped it or how.
    --
    -- ★ AND IT EXPLAINS NOTHING. No channel, no address, no reason, no evidence, no estate name, no
    -- asset, no count, no other party, and no word that could read as an accusation. A claimant who
    -- acted in good faith and a claimant who did not receive the identical sentence, because this
    -- routine cannot tell them apart and must not appear to.
    --
    -- ★ CATEGORY `claimUpdate` IS DELIBERATE AND COSTS THE CLIENT NOTHING. It is already in the RN
    -- client's KNOWN_CATEGORIES with the label "Claim update", and no server event used it before —
    -- so this event decodes exactly rather than degrading to `other` ("Account update"). Inventing a
    -- new category would have required a mobile release to render this event honestly.
    ('death_process.halted',        'claimUpdate',  'Estate process halted',
     'The estate process you initiated has been halted.')
  ) as c(event, category, title, body)
  where c.event = p_event;
$function$;

comment on function public.notification_event_copy(text) is
  'Immutable closed catalog of lifecycle notification copy, keyed by event name. Returns ZERO rows '
  'for an unknown event, which emit_lifecycle_notification treats as a refusal to emit. This is the '
  'ONLY place notification copy exists; emitters name an event and never compose text.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- ★ THE DEATH / CLAIM FIREWALL, EXPRESSED AS A REFUSAL TO EMIT.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- "You have access" may be said ONLY about a grant that confers access AT THIS MOMENT. A grant
-- conditioned on death, on a claim decision, or on identity verification confers nothing yet, and a
-- notification saying otherwise would be the release announcement Phase 11 has not built.
--
-- ★ IT MIRRORS `can_access_document`'S RELEASE RULE, AND MIRRORS IT RATHER THAN GUESSING AT IT.
--
-- The active set is: `immediately` always, plus the two approval-conditioned states once
-- `approved_at` is set — `after_owner_approval` and `after_access_request_approval` being the same
-- gate seen from the two initiators. Everything else is dormant-deny.
--
-- Enumerating what it REFUSES is the load-bearing half, so it is written down rather than implied:
--
--   never                              nothing is ever released
--   after_verified_death_or_incapacity ★ the death firewall — dormant, and stays dormant
--   after_claim_case_approval          ★ an APPROVED claim releases NOTHING and announces NOTHING
--   after_identity_verification        not a release signal this product acts on yet
--
-- ★ AND THE DIRECTION OF ERROR IS CHOSEN. A notification that announces access a read would then
-- refuse is the failure that matters — it tells a person something false about their own standing
-- and sends them to a screen that says no. Every state accepted here is accepted by
-- `can_access_document`, so that cannot happen. The reverse (staying quiet about something the
-- reader would allow) costs a heads-up and nothing else.
--
-- This is NOT a second copy of the authorization rule and must never grow into one. It decides
-- whether to SPEAK; it never decides what may be READ, and no read path consults it.
create or replace function public.notification_grant_is_live(
  p_status text,
  p_release_condition text,
  p_approved_at timestamptz
)
 returns boolean
 language sql
 immutable
 set search_path to 'public'
as $function$
  -- ★ PHASE 11-B — the release rule is no longer written here. This was one of seven copies of it;
  -- it is now one call to the canonical authority, under the SAME `'standard'` policy
  -- `can_access_document` uses. That is what makes the paragraph above ("every state accepted here
  -- is accepted by can_access_document") a structural fact rather than a claim two files apart have
  -- to keep agreeing about by hand.
  --
  -- ★ PHASE 11-D — THE LIFECYCLE ARGUMENT IS PINNED TO THE BASE STATE, DELIBERATELY. This predicate
  -- decides whether to SPEAK, and it may speak only about access that holds WITHOUT reference to any
  -- lifecycle event: a "You have access" emitted because an estate is death_verified IS the release
  -- announcement Phase 11-F owns the copy for, and 11-D emits no death or release fact (R11, §16).
  -- Pinning 'active' keeps every emission byte-identical to Phase 10-E — which the source↔deployment
  -- reconciler requires (this function's full truth table is compared EXACT against production) —
  -- and keeps the subset property: everything accepted here is still accepted by the read path,
  -- while the read path may now accept more. The quiet direction costs a heads-up and nothing else.
  -- This literal is the ONE sanctioned non-seam lifecycle argument in the codebase, pinned by
  -- `test/deathVerificationFoundation.test.ts`; every disclosure evaluator passes
  -- `public.estate_lifecycle_state(<estate>)`.
  --
  -- The STATUS half stays here, because it is not a release-condition question: a revoked grant is
  -- not a dormant condition, it is a grant that no longer exists for this purpose.
  select p_status = 'active'
     and public.release_condition_satisfied(p_release_condition, p_approved_at, 'standard', 'active');
$function$;

comment on function public.notification_grant_is_live(text, text, timestamptz) is
  'True only for a grant that confers access in the BASE lifecycle, a deliberate subset of '
  'can_access_document''s rule since 11-D: the lifecycle argument is pinned to active, so a '
  'death-conditioned grant emits NOTHING even at death_verified — release announcements are 11-F '
  'copy, not a side effect of grant emission. Claim-conditioned grants stay dormant. Decides whether '
  'to SPEAK, never what may be READ — no read path consults it.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- Recipient resolution. Server-side, from the authoritative source for each fact.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ IDENTITY AND RELATIONSHIP ARE NEVER RECONSTRUCTED FROM CAPABILITIES. Ownership comes from
-- `estates.owner_id` (the same column `is_estate_owner` reads, kept to the sanctioned single site);
-- the grantee comes from the grant row; the requester comes from the request row. No recipient is
-- ever inferred from a permission combination.
create or replace function public.estate_owner_user_id(p_estate_id uuid)
 returns uuid
 language sql
 stable
 security definer
 set search_path to 'public'
as $function$
  select owner_id from public.estates where id = p_estate_id;
$function$;

comment on function public.estate_owner_user_id(uuid) is
  'The estate owner user id, for server-side notification recipient resolution. INTERNAL: execute is '
  'revoked from public/authenticated, because a client that can map estate -> owner identity has been '
  'handed an identity-disclosure surface nothing in the product offers.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- Deep-link target. A CLOSED SET OF TWO, chosen server-side from authoritative membership.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ A DEEP LINK IS NOT A BEARER TOKEN, AND THIS FUNCTION IS NOT AN AUTHORIZATION. Both destinations
-- re-fetch their own authority on arrival and refuse independently — `get_professional_workspace`
-- and `get_estate_discovery` each answer for themselves, and a notification that outlived a
-- revocation simply lands on a refusal. Choosing WHICH of the two is a routing convenience, not a
-- grant, and the value discloses nothing: both routes exist for every participant.
--
-- It is derived server-side rather than client-side for the reason in the phase brief — the client
-- must not decide who should know what — even though in this instance the choice is inert.
create or replace function public.notification_estate_home(p_estate_id uuid, p_user_id uuid)
 returns text
 language sql
 stable
 security definer
 set search_path to 'public'
as $function$
  select case
    when exists (
      select 1 from public.estate_memberships m
      where m.estate_id = p_estate_id
        and m.user_id = p_user_id
        and m.role = 'professional_delegate'
        and m.status = 'approved'
    ) then 'afterworth://workspace'
    else 'afterworth://estate-summary'
  end;
$function$;

comment on function public.notification_estate_home(uuid, uuid) is
  'Closed set of two in-app destinations for a lifecycle notification, chosen from authoritative '
  'membership. Not an authorization: both destinations re-check their own authority on arrival.';

-- ────────────────────────────────────────────────────────────────────────────────────────────────
-- ★ THE ONE WAY A LIFECYCLE NOTIFICATION IS WRITTEN.
-- ────────────────────────────────────────────────────────────────────────────────────────────────
--
-- ★ TRANSACTIONAL SEMANTICS, STATED EXACTLY. A plpgsql function runs inside its CALLER'S
-- transaction, so this insert and the state transition that triggered it commit or roll back
-- TOGETHER. If the transition rolls back, the notification never existed. There is no queue, no
-- outbox and no window in which a notification describes something that did not happen.
--
-- The one asymmetry is deliberate and is the existing convention: if the notification insert itself
-- fails, the load-bearing event still commits. A grant is the product; a heads-up is not, and
-- failing a grant because a notification could not be written would be the wrong trade.
--
-- ★ BUT SILENT DEGRADATION IS OPERATIONAL DEBT, SO IT IS NOT SILENT. The previous convention was
-- `exception when others then null` copied into each call site — which swallows the failure AND
-- relies on every future emitter remembering to write it. Here it is swallowed in ONE place and
-- raises a WARNING, so the failure is visible to an engineer in the Postgres log rather than
-- inferred later from a missing row.
--
-- ★ AN UNKNOWN EVENT EMITS NOTHING. It does not fall back to a generic message. A fallback would
-- mean a typo produces a real notification with invented meaning, which is precisely the class of
-- bug that put a raw enum in front of a user.
create or replace function public.emit_lifecycle_notification(
  p_user_id uuid,
  p_estate_id uuid,
  p_event text,
  p_deep_link text default null
)
 returns uuid
 language plpgsql
 volatile
 security definer
 set search_path to 'public'
as $function$
declare
  v_copy record;
  v_id uuid;
begin
  -- No recipient, no notification. A null here means a caller could not resolve one, and inventing
  -- a recipient is the one mistake this whole file exists to prevent.
  if p_user_id is null or p_event is null then
    return null;
  end if;

  select c.category, c.title, c.body into v_copy
  from public.notification_event_copy(p_event) c;

  if v_copy is null then
    raise warning 'emit_lifecycle_notification: unknown event %, nothing emitted', p_event;
    return null;
  end if;

  begin
    v_id := public.emit_notification(
      p_user_id, p_estate_id, v_copy.category, v_copy.title, v_copy.body, p_deep_link, '{}'::jsonb
    );
  exception when others then
    -- Swallowed so the load-bearing transition still commits — but LOUD in the server log.
    raise warning 'emit_lifecycle_notification: event % could not be written (%)', p_event, sqlerrm;
    return null;
  end;

  return v_id;
end;
$function$;

comment on function public.emit_lifecycle_notification(uuid, uuid, text, text) is
  'The only way a lifecycle notification is written. Copy comes from the immutable event catalog; '
  'callers name an event and never compose text. Runs in the caller transaction, so it commits or '
  'rolls back with the state transition. INTERNAL: execute revoked from public/authenticated.';

-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- ★ EVERY PRIVILEGE STATEMENT FOR THESE FUNCTIONS LIVES IN 0050, AND NOT HERE.
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- The revokes were originally written in BOTH this file and the migration, on the reasoning that a
-- function and its access model belong together. Mutation testing killed that idea in the most
-- direct way available: `forgery-lock-removed` flipped the migration's
-- `revoke execute ... from authenticated` to a `grant`, and the SUITE STILL PASSED — because this
-- file re-revoked it moments later, from the same bundle.
--
-- Two copies of a security control are not defence in depth when they run in sequence. They are one
-- control and one thing that silently repairs an attempt to remove it, which is strictly worse than
-- one control: it makes the hole un-testable, and it would have made a future `grant` in the
-- migration look harmless in review.
--
-- So the privilege model is single-sourced in `db/migrations/0050_20260811_lifecycle_notifications.sql`,
-- which the bundle loads AFTER this file precisely so every function exists by the time it runs.
-- The mutation is killed now.


-- ==== db/migrations/0050_20260811_lifecycle_notifications.sql =====================================
-- 0050 — Phase 10-E lifecycle notifications.
--
-- The notification STORE already exists (0009 reconciled it from live and gave it self-scoped RLS
-- plus the anti-forge lock). This migration adds nothing to the store's shape. It does two things:
-- it closes a privilege hole 0009 left open, and it adds the index the unread path deserves.
--
-- The emission spine and the rewritten emitters are functions and travel in
-- `db/bundles/lifecycle_notifications_bundle.sql`, which includes this file as its first part.
--
-- IDEMPOTENT: safe to re-apply. Revokes are no-ops when already revoked; the index is IF NOT EXISTS.

-- ════════════════════════════════════════════════════════════════════════════════════════════════
-- ★ HIGH — CLOSE THE FORGERY HOLE. `emit_notification` COULD BE CALLED BY ANY AUTHENTICATED USER.
-- ════════════════════════════════════════════════════════════════════════════════════════════════
--
-- 0009 revoked INSERT on `public.notifications` from `authenticated`, enabled self-scoped RLS, and
-- recorded the posture as: "a client calling emit_notification directly can still only create a
-- notification (it can't read others' — that's RLS on SELECT)."
--
-- That reasoned about READ and never about WRITE-TO-SOMEONE-ELSE. `emit_notification` is SECURITY
-- DEFINER, is exposed by PostgREST, takes `p_user_id` AS A PARAMETER, and — like every Postgres
-- function — was granted EXECUTE to PUBLIC by default. So any authenticated user could write an
-- arbitrary title, body and `action_deep_link` into ANY other user's notification centre. RLS on
-- SELECT is no defence: the victim is supposed to read it. That is the entire attack.
--
-- CONFIRMED AGAINST THE DEPLOYED DATABASE BEFORE THIS WAS WRITTEN, without creating a row: called as
-- an ordinary authenticated fixture user with a non-UUID argument it answered
-- `22P02 invalid input syntax for type uuid` — a coercion failure, which happens AFTER the EXECUTE
-- check, and identical to the answer from a routine the product genuinely grants. A `42501` would
-- have meant the privilege was already absent. It was not.
--
-- It matters more in 10-E than it did before: lifecycle notifications carry real deep links and ask
-- users to trust this surface, so a forged "Access request approved" with a link is a credible
-- phishing primitive rather than a curiosity.
--
-- SAFE: no client calls it. The mobile notification service states outright that there is nothing to
-- create there, and the endpoint exposes only list / mark_read / mark_all_read / unread_count. Every
-- real caller is a SECURITY DEFINER function executing as the owner, who retains EXECUTE inherently.
revoke execute on function public.emit_notification(uuid, uuid, text, text, text, text, jsonb) from public;
revoke execute on function public.emit_notification(uuid, uuid, text, text, text, text, jsonb) from anon;
revoke execute on function public.emit_notification(uuid, uuid, text, text, text, text, jsonb) from authenticated;

-- ★ THE 10-E SPINE IS INTERNAL TOO, AND THESE REVOKES LIVE HERE RATHER THAN BESIDE THE FUNCTIONS.
--
-- They were originally written in both places, which felt tidier and was actively harmful: mutation
-- testing flipped the `emit_notification` revoke above to a `grant` and the authorization suite
-- still passed, because the duplicate in `lifecycle_notification_rpcs.sql` re-revoked it moments
-- later from the same bundle. Two copies of a control that run in sequence are not defence in depth;
-- they are one control plus a mechanism that silently repairs attempts to remove it, which makes the
-- hole untestable and would make a future `grant` look harmless in review.
--
-- Single-sourced here. The bundle loads this file AFTER the function definitions so every name below
-- exists by the time it runs.
revoke execute on function public.emit_lifecycle_notification(uuid, uuid, text, text) from public;
revoke execute on function public.emit_lifecycle_notification(uuid, uuid, text, text) from anon;
revoke execute on function public.emit_lifecycle_notification(uuid, uuid, text, text) from authenticated;

-- Recipient resolution is internal for the same reason: a client able to map estate -> owner id, or
-- to ask which destination another user would be routed to, has been handed a membership oracle.
revoke execute on function public.estate_owner_user_id(uuid) from public;
revoke execute on function public.estate_owner_user_id(uuid) from anon;
revoke execute on function public.estate_owner_user_id(uuid) from authenticated;

revoke execute on function public.notification_estate_home(uuid, uuid) from public;
revoke execute on function public.notification_estate_home(uuid, uuid) from anon;
revoke execute on function public.notification_estate_home(uuid, uuid) from authenticated;

-- The two pure catalog functions (`notification_event_copy`, `notification_grant_is_live`) are left
-- callable. Neither reads a row; one returns product copy, the other a boolean over two literals.
-- Revoking them would be ceremony, and ceremony around a security control makes the real ones harder
-- to see.

-- ★ THE UNREAD PATH HAS ITS OWN SHAPE. `notifications_recipient_idx (user_id, created_at desc)` from
-- 0009 serves the list; the badge counts unread for one user, which is a different leading edge.
-- Partial, because the read rows are the ones that accumulate and none of them are ever counted.
create index if not exists notifications_unread_idx
  on public.notifications (user_id)
  where read = false;

comment on table public.notifications is
  'Self-scoped notification store. Rows are written ONLY by SECURITY DEFINER emitters — authenticated '
  'holds no INSERT grant and, since 0050, no EXECUTE on emit_notification either. Lifecycle copy is a '
  'constant looked up by event name in notification_event_copy; no emitter composes or interpolates text.';


-- ==== db/functions/create_access_request.sql ======================================================
-- public.create_access_request(p_estate_id uuid, p_category text default 'estate_documents',
--                              p_reason text default null)
--   -> SETOF public.access_requests   (the created request row)
--
-- A NON-owner member of the estate requests access to a category ('estate_documents' in V1);
-- the owner later converts it to an already-approved grant via approve_access_request.
--
-- SECURITY (load-bearing): SECURITY DEFINER bypasses RLS, so the explicit gate below IS the
-- boundary. requester_user_id is STAMPED = auth.uid() (never a client param — anti-spoof,
-- the same discipline as granted_by_user_id on grants). The MEMBER gate is the INVERSE of
-- the owner RPCs: an APPROVED estate_membership for auth.uid() AND a non-ownership role
-- (owners have inherent access — a request is meaningless, and is rejected). Non-member -> 42501.
--
-- requester_role: captured in the SAME membership lookup the gate performs (no second query)
-- and STAMPED onto the row, so the owner-review surface can show the SCOPE of an approval
-- (approving a professional_delegate grants RESTRICTED-doc access — more than a beneficiary;
-- document_grantable keys on role). The gate changed from an EXISTS to a SELECT ... INTO so
-- the one lookup both gates AND returns the role.
--
-- Dedup: the access_requests_one_pending partial unique (one pending per estate,requester,
-- category) fires on insert; surfaced as a readable 409.
--
-- Error codes (SQLSTATE -> PostgREST HTTP status):
--   42501 -> 403  unauthenticated / not an eligible member (privilege gate)
--   23505 -> 409  a pending request already exists for this (estate, requester, category)
--   P0001 -> 400  unsupported category (default RAISE sqlstate)
--
-- SECURITY DEFINER; relies on auth.uid(). Source of truth — re-apply on DB reset.

create or replace function public.create_access_request(
  p_estate_id uuid,
  p_category text default 'estate_documents',
  p_reason text default null
)
 returns setof public.access_requests
 language plpgsql
 security definer
 set search_path to 'public', 'extensions'
as $function$
declare
  v_user uuid := auth.uid();
  v_requester_role text;
  v_id uuid;
begin
  -- Auth null-guard.
  if v_user is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  -- Category validation (V1: estate_documents only). Belt-and-suspenders with the table
  -- CHECK — a clean 400 instead of a raw constraint error.
  if p_category is distinct from 'estate_documents' then
    raise exception 'unsupported request category';  -- P0001 -> 400
  end if;

  -- MEMBER GATE + ROLE CAPTURE in ONE lookup (privilege boundary; DEFINER bypasses RLS, so
  -- this explicit check IS the access boundary). The ownership exclusion stays IN the WHERE
  -- (NOT a post-LIMIT check): a single (estate, user) is NOT guaranteed to have only one
  -- approved membership (accept_invitation inserts with no (estate,user) uniqueness; V2 adds
  -- more ownership roles), so a status-only select + post-check would be nondeterministic —
  -- it could grab an ownership row and wrongly reject a user who also has a non-ownership row.
  -- Filtering here makes this provably equivalent to the original EXISTS (passes iff an
  -- approved NON-ownership membership exists) AND captures that surviving role to stamp.
  select m.role into v_requester_role
  from public.estate_memberships m
  where m.estate_id = p_estate_id
    and m.user_id = v_user
    and m.status = 'approved'
    and not public.is_ownership_role(m.role)
  limit 1;

  if v_requester_role is null then
    raise exception 'not an estate member eligible to request access'
      using errcode = '42501';
  end if;

  -- Insert. requester_user_id + requester_role STAMPED server-side (never params). The
  -- one-pending partial unique fires here; surface a readable 409.
  begin
    insert into public.access_requests
      (estate_id, requester_user_id, requester_role, category, reason, status)
    values
      (p_estate_id, v_user, v_requester_role, p_category, p_reason, 'pending')
    returning id into v_id;
  exception
    when unique_violation then
      raise exception
        'a pending access request already exists for this category; await a decision'
        using errcode = '23505';   -- -> 409 Conflict
  end;

  perform public.write_audit(
    'access_request.created',
    'access_requests',
    v_id,
    p_estate_id,
    jsonb_build_object('category', p_category, 'requester_role', v_requester_role)
  );

  -- ★ PHASE 10-E — the OWNER learns a request is waiting. Emitted AFTER the insert succeeded, in the
  -- SAME transaction: if the insert had raised (the one-pending unique violation above), control
  -- never reaches here, and if anything later rolls the transaction back the notification goes with
  -- it. The recipient comes from `estates.owner_id`, never from a capability combination.
  perform public.emit_lifecycle_notification(
    public.estate_owner_user_id(p_estate_id),
    p_estate_id,
    'access_request.created',
    'afterworth://owner-review'
  );

  return query select r.* from public.access_requests r where r.id = v_id;
end;
$function$;


-- ==== db/functions/approve_access_request.sql =====================================================
-- public.approve_access_request(p_request_id uuid, p_visibility_tier text default 'limited_detail')
--   -> SETOF public.access_requests   (the approved request row, incl. resulting_grant_id)
--
-- Owner-gated approval of a beneficiary-initiated access request. ATOMIC, one-step:
-- creates an ALREADY-APPROVED category grant (category = request.category, document_id
-- null, release_condition = 'after_access_request_approval', approved_at = now()) AND
-- marks the request approved — both in this single plpgsql function, i.e. ONE transaction,
-- so they commit or roll back together. A failed grant insert leaves the request pending.
--
-- INLINE insert (not create_document_grant — that RPC is document-only, category null by
-- design). Promote to a create_category_grant RPC when the Assets path needs general
-- category grants; until then this is the only category-grant site.
--
-- TIER: the owner chooses disclosure via p_visibility_tier; default 'limited_detail'
-- (conservative — mirrors the sealed-default philosophy). Restricted to the two
-- document-meaningful tiers (matches the grant UI's tierOptions); a bad tier -> clean 400,
-- not a raw CHECK 500.
--
-- CEILING: enforce_grant_ceiling NO-OPs on a category grant (document_id null), so there
-- is no approval-time ceiling rejection. The ceiling is enforced AT READ, per-document, in
-- can_access_document (document_grantable) — a sealed/restricted doc stays hidden from the
-- grantee even with this category grant.
--
-- ALREADY-GRANTED: if an active category grant already exists for (estate, grantee,
-- category) (the access_grants one-active-category partial unique), the insert raises
-- 23505; we CATCH it, link the EXISTING grant via resulting_grant_id, and still mark the
-- request approved — idempotent, no duplicate, no error.
--
-- Error codes (SQLSTATE -> PostgREST HTTP status):
--   42501 -> 403  unauthenticated / not_estate_owner (privilege gate)
--   P0001 -> 400  request_not_found / request_not_pending / unsupported tier /
--                 requester no longer a member (default RAISE sqlstate)
--
-- SECURITY DEFINER; relies on auth.uid(). Source of truth — re-apply on DB reset.

create or replace function public.approve_access_request(
  p_request_id uuid,
  p_visibility_tier text default 'limited_detail'
)
 returns setof public.access_requests
 language plpgsql
 security definer
 set search_path to 'public', 'extensions'
as $function$
declare
  v_user      uuid := auth.uid();
  v_estate    uuid;
  v_requester uuid;
  v_category  text;
  v_status    text;
  v_role      text;
  v_grant_id  uuid;
begin
  if v_user is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  -- Lock the request row for the txn (no concurrent double-approve).
  select estate_id, requester_user_id, category, status
    into v_estate, v_requester, v_category, v_status
  from public.access_requests
  where id = p_request_id
  for update;

  if v_estate is null then
    raise exception 'request_not_found';  -- P0001 -> 400
  end if;

  -- SECURITY SPINE (privilege gate): owner-only, BEFORE any mutation.
  if not public.is_estate_owner(v_estate) then
    raise exception 'not estate owner' using errcode = '42501';
  end if;

  -- Only a pending request can be approved (prevents double-approve / duplicate grant).
  if v_status is distinct from 'pending' then
    raise exception 'request_not_pending';  -- P0001 -> 400
  end if;

  -- Owner-chosen disclosure tier; restrict to the two document-meaningful tiers (mirrors
  -- the grant UI's tierOptions). Avoids a raw CHECK violation (500) on a bad tier.
  if p_visibility_tier not in ('full_detail','limited_detail') then
    raise exception 'unsupported visibility tier';  -- P0001 -> 400
  end if;

  -- Resolve the requester's CURRENT NON-OWNERSHIP role in the estate (for grantee_role + the
  -- ceiling matrix). The ownership exclusion stays IN the WHERE (mirrors create_access_request):
  -- a (estate, user) may have >1 approved membership (no (estate,user) uniqueness — accept_
  -- invitation keys idempotency on source_invitation_id; V2 adds ownership roles). A status-only
  -- lookup could grab an OWNERSHIP row and stamp grantee_role='primary_user', which the
  -- access_grants.grantee_role CHECK rejects -> a 500 on approval. Filtering here keeps
  -- grantee_role valid AND resolves the role the SAME way the request's requester_role was stamped.
  select m.role into v_role
  from public.estate_memberships m
  where m.estate_id = v_estate
    and m.user_id = v_requester
    and m.status = 'approved'
    and not public.is_ownership_role(m.role)
  limit 1;

  -- Null = the requester is no longer an approved non-ownership member (revoked between request
  -- and approval, or now only an ownership role). Clean 400 with a readable message — NOT a 500.
  if v_role is null then
    raise exception 'requester is no longer an eligible member of this estate';  -- P0001 -> 400
  end if;

  -- Create the ALREADY-APPROVED category grant (inline; create_document_grant is doc-only).
  -- enforce_grant_ceiling no-ops here (document_id null). The one-active-category-grant
  -- unique index may fire -> already-granted path in the handler below.
  begin
    insert into public.access_grants
      (estate_id, grantee_user_id, grantee_role, professional_type,
       document_id, category, visibility_tier, release_condition,
       requires_step_up, status, granted_by_user_id,
       approved_at, approved_by_user_id)
    values
      (v_estate, v_requester, v_role, null,
       null, v_category, p_visibility_tier, 'after_access_request_approval',
       false, 'active', v_user,
       now(), v_user)
    returning id into v_grant_id;
  exception
    when unique_violation then
      -- Already-granted: an active category grant exists for this grantee. Link it, mark
      -- the request approved, no duplicate, no error (idempotent).
      select g.id into v_grant_id
      from public.access_grants g
      where g.estate_id = v_estate
        and g.grantee_user_id = v_requester
        and g.category = v_category
        and g.status = 'active'
      limit 1;
  end;

  update public.access_requests
     set status = 'approved',
         resolved_at = now(),
         resolved_by_user_id = v_user,
         resulting_grant_id = v_grant_id
   where id = p_request_id;

  perform public.write_audit(
    'access_request.approved',
    'access_requests',
    p_request_id,
    v_estate,
    jsonb_build_object(
      'grant_id', v_grant_id,
      'category', v_category,
      'grantee_user_id', v_requester,
      'visibility_tier', p_visibility_tier
    )
  );

  -- ★ PHASE 10-E — the REQUESTER learns the outcome of THEIR OWN request, and nothing else. The copy
  -- says the request was approved; it does not say what became visible, which tier was chosen, or
  -- what the estate contains. One notification, not two: the grant created above deliberately does
  -- NOT also emit `access_grant.created`, because a person who asked one question should get one
  -- answer.
  perform public.emit_lifecycle_notification(
    v_requester,
    v_estate,
    'access_request.approved',
    public.notification_estate_home(v_estate, v_requester)
  );

  return query select r.* from public.access_requests r where r.id = p_request_id;
end;
$function$;


-- ==== db/functions/deny_access_request.sql ========================================================
-- public.deny_access_request(p_request_id uuid)
--   -> SETOF public.access_requests   (the denied request row)
--
-- Owner-gated denial of a PENDING access request. Marks it denied; creates NO grant. A
-- denied request frees the one-pending partial-unique slot, so the requester may
-- re-request (a new pending row). Denial-with-reason is deferred (matches the slice's
-- defer list).
--
-- Error codes (SQLSTATE -> PostgREST HTTP status):
--   42501 -> 403  unauthenticated / not_estate_owner (privilege gate)
--   P0001 -> 400  request_not_found / request_not_pending (default RAISE sqlstate)
--
-- SECURITY DEFINER; relies on auth.uid(). Source of truth — re-apply on DB reset.

create or replace function public.deny_access_request(p_request_id uuid)
 returns setof public.access_requests
 language plpgsql
 security definer
 set search_path to 'public', 'extensions'
as $function$
declare
  v_user      uuid := auth.uid();
  v_estate    uuid;
  v_status    text;
  -- ★ PHASE 10-E — read alongside the estate, from the request row itself. The recipient of a
  -- decision notification is the person who made the request; it is never derived from who happens
  -- to hold a capability on this estate.
  v_requester uuid;
begin
  if v_user is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  -- Lock the request row for the txn.
  select estate_id, status, requester_user_id into v_estate, v_status, v_requester
  from public.access_requests
  where id = p_request_id
  for update;

  if v_estate is null then
    raise exception 'request_not_found';  -- P0001 -> 400
  end if;

  -- SECURITY SPINE (privilege gate): owner-only, BEFORE any mutation.
  if not public.is_estate_owner(v_estate) then
    raise exception 'not estate owner' using errcode = '42501';
  end if;

  if v_status is distinct from 'pending' then
    raise exception 'request_not_pending';  -- P0001 -> 400
  end if;

  update public.access_requests
     set status = 'denied',
         resolved_at = now(),
         resolved_by_user_id = v_user
   where id = p_request_id;

  perform public.write_audit(
    'access_request.denied',
    'access_requests',
    p_request_id,
    v_estate,
    jsonb_build_object('outcome', 'denied')
  );

  -- ★ PHASE 10-E — the REQUESTER learns the outcome of THEIR OWN request. Only they receive it: a
  -- denial is not estate news, and no other member is told that someone asked and was refused.
  --
  -- NO DEEP LINK. There is nothing newly available to open, and sending a refused requester to an
  -- estate surface would be an invitation to a screen that says no.
  perform public.emit_lifecycle_notification(
    v_requester,
    v_estate,
    'access_request.denied',
    null
  );

  return query select r.* from public.access_requests r where r.id = p_request_id;
end;
$function$;


-- ==== db/functions/create_asset_grant.sql =========================================================
-- public.create_asset_grant(
--   p_estate_id uuid, p_grantee_user_id uuid, p_grantee_role text,
--   p_category text, p_visibility_tier text, p_release_condition text,
--   p_professional_type text default null, p_requires_step_up boolean default false)
--   -> SETOF public.access_grants   (the created grant row)
--
-- B2b — the audited, single-entry interface for creating a CATEGORY-scoped ASSET disclosure grant
-- (the connected-financial-data counterpart of create_document_grant, which is document-only by
-- design). Category-scoped: takes p_category (one of the asset categories), never a document_id —
-- the document_id XOR category table invariant is satisfied structurally (document_id stays NULL).
--
-- WRITE-TIME CEILING (the load-bearing addition): the enforce_grant_ceiling TRIGGER only fires for
-- per-document grants (new.document_id is not null), so category grants bypass it. This RPC enforces
-- the asset ceiling explicitly via asset_category_grantable(role, category, tier) BEFORE the insert —
-- an over-ceiling grant (e.g. beneficiary + account_balances + full_detail) is REJECTED at write, not
-- merely clamped at read. B2a's read-time clamp in list_estate_assets remains the backstop, so a bad
-- grant can neither be stored (this) nor leak (that). Defense-in-depth on a financial-disclosure grant.
--
-- SECURITY (load-bearing): SECURITY DEFINER runs as the table owner and BYPASSES RLS, so the
-- access_grants_insert WITH CHECK (is_estate_owner) does NOT auto-apply. The explicit
-- is_estate_owner(p_estate_id) check below IS the access boundary — FIRST check after the auth.uid()
-- null-guard, BEFORE any insert. Without it any authenticated user could grant themselves access.
--
-- Pre-granting is allowed (matches create_document_grant + the B2a grant-based read): the RPC does
-- NOT require the grantee to be a member. A grant to a uid that hasn't joined is inert until that uid
-- authenticates (access re-evaluated at read against auth.uid()) — no hole, an unmatched grant never
-- activates.
--
-- UUID-case: p_grantee_user_id is uuid-typed -> Postgres canonicalizes to lowercase automatically.
--
-- Error codes (SQLSTATE -> PostgREST HTTP; only mapped SQLSTATEs avoid 500):
--   42501 -> 403  unauthenticated / not_estate_owner (privilege gate) / ceiling violation
--   23505 -> 409  duplicate: an active grant already exists for this category + grantee
--   P0001 -> 400  validation: owner_grant (self/owner) OR invalid asset category
--
-- SECURITY DEFINER; relies on auth.uid(). Source of truth — re-apply on DB reset.

create or replace function public.create_asset_grant(
  p_estate_id uuid,
  p_grantee_user_id uuid,
  p_grantee_role text,
  p_category text,
  p_visibility_tier text,
  p_release_condition text,
  p_professional_type text default null,
  p_requires_step_up boolean default false
)
 returns setof public.access_grants
 language plpgsql
 security definer
 set search_path to 'public', 'extensions'
as $function$
declare
  v_user uuid := auth.uid();
  v_id uuid;
begin
  -- Auth null-guard.
  if v_user is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  -- SECURITY SPINE (privilege-escalation gate). DEFINER bypasses RLS, so this explicit owner-check
  -- IS the access boundary and MUST precede any insert.
  if not public.is_estate_owner(p_estate_id) then
    raise exception 'not estate owner' using errcode = '42501';
  end if;

  -- No grants to owners (self, or any ownership-role member) — inherent access.
  if p_grantee_user_id = v_user
     or exists (
       select 1 from public.estate_memberships m
       where m.estate_id = p_estate_id
         and m.user_id = p_grantee_user_id
         and public.is_ownership_role(m.role)
     ) then
    raise exception 'cannot grant access to an owner; owners have inherent access';  -- P0001 -> 400
  end if;

  -- Category must be a real ASSET category (defense-in-depth beyond the access_grants.category CHECK;
  -- the RPC is the security boundary and may be called directly).
  --
  -- ★ `estate_inventory` IS IN THIS LIST IN VERSION CONTROL — AND UNTIL PHASE 10-E IT WAS NOT.
  --
  -- Migration 0049 adds it to the DEPLOYED body by string surgery: it reads `pg_get_functiondef`,
  -- replaces this exact literal, and re-executes. So production has had the widened list for weeks
  -- while this file — the supposed source of truth — still refused the category.
  --
  -- That is the live-only-object trap this repository has been bitten by repeatedly (handle_new_user,
  -- is_estate_owner, the whole 0009 notifications table), except inverted and more dangerous: the
  -- object WAS in version control, and the version-controlled copy was WRONG. Re-applying this file
  -- would have silently reverted Phase 9/10-A grantability, and nothing would have caught it — the
  -- deployed-contract verifier checks `asset_category_grantable`, which is a DIFFERENT function and
  -- would have stayed green.
  --
  -- It became reachable in Phase 10-E because this file now ships in a bundle. Fixed at the source
  -- rather than by ordering the bundles carefully, because an ordering rule is a thing to remember
  -- and a correct source file is not. 0049's patch is guarded by `if position('estate_inventory' in
  -- v_src) = 0`, so it now finds the category already present and does nothing — still correct for a
  -- database that predates this fix, a no-op for one that does not.
  if p_category not in
     ('account_balances', 'institution_names', 'total_asset_value', 'linked_account_details', 'estate_inventory') then
    raise exception 'invalid asset category: %', p_category;  -- P0001 -> 400
  end if;

  -- ★ WRITE-TIME RELEASE VOCABULARY (Phase 11-B). The table CHECK still accepts the deprecated
  --   `after_verified_death_or_incapacity` so stored rows stay readable and unreinterpreted; this
  --   gate is what stops a NEW row from carrying the fused ambiguity. Death and incapacity are now
  --   expressible separately — and neither is satisfied by anything, so this widens what an owner
  --   may EXPRESS, never what a grantee may SEE.
  if not public.release_condition_writable(p_release_condition) then
    raise exception 'unsupported release condition: %', p_release_condition;  -- P0001 -> 400
  end if;

  -- ★ WRITE-TIME CEILING — reject an over-ceiling grant before storing it (the trigger skips category
  --   grants). Mirrors the read-time clamp in list_estate_assets: e.g. beneficiary + account_balances
  --   + full_detail -> asset_category_grantable = false -> rejected here.
  if not public.asset_category_grantable(p_grantee_role, p_category, p_visibility_tier) then
    raise exception 'asset grant ceiling: role % cannot be granted tier % for category %',
      p_grantee_role, p_visibility_tier, p_category
      using errcode = '42501';   -- ceiling violation -> 403 (mirrors document_grantable)
  end if;

  -- Insert (category-scoped: document_id NULL). Table CHECKs + the one-active-grant-per-(estate,
  -- grantee,category) unique index fire regardless of the DEFINER context. Catch the unique
  -- violation and surface a readable 409 (fail, never silent upsert — a silent tier change on a
  -- disclosure grant is dangerous; a tier change is revoke + re-create).
  begin
    insert into public.access_grants
      (estate_id, grantee_user_id, grantee_role, professional_type,
       document_id, category, visibility_tier, release_condition,
       requires_step_up, granted_by_user_id)
    values
      (p_estate_id, p_grantee_user_id, p_grantee_role, p_professional_type,
       null, p_category, p_visibility_tier, p_release_condition,
       p_requires_step_up, v_user)
    returning id into v_id;
  exception
    when unique_violation then
      raise exception
        'an active grant already exists for this category and grantee; revoke it first'
        using errcode = '23505';   -- unique_violation -> 409 Conflict
  end;

  perform public.write_audit(
    'access_grant.created',
    'access_grants',
    v_id,
    p_estate_id,
    jsonb_build_object(
      'grantee_user_id', p_grantee_user_id,
      'grantee_role', p_grantee_role,
      'category', p_category,
      'visibility_tier', p_visibility_tier,
      'release_condition', p_release_condition
    )
  );

  -- ★ PHASE 10-E — REWRITTEN, AND THE PREVIOUS VERSION WAS A LIVE DEFECT ON TWO COUNTS.
  --
  -- It read:
  --     'You''ve been granted access to estate assets (' || p_category || ').'
  --     'afterworth://accounts'
  --     jsonb_build_object('kind','grant_created','grant_id', v_id, 'category', p_category)
  --
  -- 1. It concatenated `p_category` — a backend enum — into user-facing prose. The one lifecycle
  --    notification in production reads "...to estate assets (estate_inventory)." on a real device.
  --    The mobile client HAS an audit forbidding backend vocabulary on screen; it never fired,
  --    because the enum arrived as server-authored copy rather than as a client-rendered value.
  --    This is exactly why copy is now a constant looked up by event name.
  -- 2. `afterworth://accounts` is not a route this app has (the route is `/assets`), so the link was
  --    inert — fail-closed by the client allowlist, but a promise the product could not keep.
  --    The payload additionally carried a raw grant id and category, which nothing needs.
  --
  -- ★ AND IT EMITTED UNCONDITIONALLY, WHICH IS THE MORE SERIOUS HALF. "You have access" was sent for
  -- ANY grant this function created, including a `after_verified_death_or_incapacity` one that
  -- releases nothing and must stay dormant until Phase 11 connects activation to release. The gate
  -- below is the death/claim firewall: a grant that is not live RIGHT NOW produces silence.
  --
  -- ★ THE GATE READS THE STORED ROW, NOT THE PARAMETERS. `status` and `approved_at` are column
  -- DEFAULTS here — the insert names neither — so deciding from `p_release_condition` alone would be
  -- reasoning about the arguments rather than about what was actually written. A future default
  -- change, or a trigger, would silently make the parameter-based answer wrong while looking right.
  if exists (
    select 1 from public.access_grants g
    where g.id = v_id
      and public.notification_grant_is_live(g.status, g.release_condition, g.approved_at)
  ) then
    perform public.emit_lifecycle_notification(
      p_grantee_user_id,
      p_estate_id,
      'access_grant.created',
      public.notification_estate_home(p_estate_id, p_grantee_user_id)
    );
  end if;

  return query select g.* from public.access_grants g where g.id = v_id;
end;
$function$;


-- ==== db/functions/create_document_grant.sql ======================================================
-- public.create_document_grant(
--   p_estate_id uuid, p_grantee_user_id uuid, p_grantee_role text,
--   p_document_id uuid, p_visibility_tier text, p_release_condition text,
--   p_professional_type text default null, p_requires_step_up boolean default false)
--   -> SETOF public.access_grants   (the created grant row)
--
-- The audited, single-entry interface for creating a PER-DOCUMENT access grant
-- (docs/live-data-migration.md Appendix A.2). Wraps the direct INSERT into
-- public.access_grants so every grant creation runs the same owner-check, self/owner
-- rejection, ceiling, and audit. Document-scoped by design: takes p_document_id, never
-- a category — the document_id XOR category table invariant is satisfied structurally
-- (category stays NULL). Category grants get their own RPC when the Assets path is built.
--
-- SECURITY (load-bearing): SECURITY DEFINER runs as the table owner and BYPASSES RLS,
-- so the access_grants_insert WITH CHECK (is_estate_owner) does NOT auto-apply. The
-- explicit is_estate_owner(p_estate_id) check below IS the access boundary — it is the
-- FIRST check after the auth.uid() null-guard and runs BEFORE any insert. Without it,
-- ANY authenticated user could grant themselves access (privilege escalation). The
-- inherited table guards still fire on the INSERT regardless of caller: the
-- enforce_grant_ceiling trigger (restricted/sealed ceiling) and all CHECK constraints
-- + the one-active-grant-per-(estate,grantee,document) unique index.
--
-- Pre-granting is allowed: the RPC does NOT require the grantee to be an existing
-- member. A grant to a uid that hasn't joined is inert until that uid authenticates
-- (access is re-evaluated at read against auth.uid(), like beneficiaries) — no security
-- hole, an unmatched grant never activates. The RPC trusts the caller to supply a valid
-- grantee_user_id (the iOS member-picker does); it intentionally does not validate
-- grantee existence, to keep pre-granting possible.
--
-- UUID-case: p_grantee_user_id / p_document_id are uuid-typed, so Postgres canonicalizes
-- them to lowercase automatically — no manual lowercasing here.
--
-- Error codes (SQLSTATE -> PostgREST HTTP status; only mapped SQLSTATEs avoid 500):
--   42501 -> 403  unauthenticated (no auth.uid) / not_estate_owner (the privilege gate);
--                 the enforce_grant_ceiling trigger's ceiling violation surfaces here too
--   23505 -> 409  duplicate: an active grant already exists for this document + grantee
--   P0001 -> 400  validation: owner_grant (grantee is self/owner) OR document not in estate
--                 (P0001 is the default RAISE sqlstate; the two are distinguished by message)
--
-- SECURITY DEFINER; relies on auth.uid(). Source of truth — re-apply on DB reset.

create or replace function public.create_document_grant(
  p_estate_id uuid,
  p_grantee_user_id uuid,
  p_grantee_role text,
  p_document_id uuid,
  p_visibility_tier text,
  p_release_condition text,
  p_professional_type text default null,
  p_requires_step_up boolean default false
)
 returns setof public.access_grants
 language plpgsql
 security definer
 set search_path to 'public', 'extensions'
as $function$
declare
  v_user uuid := auth.uid();
  v_id uuid;
begin
  -- Auth null-guard.
  if v_user is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  -- SECURITY SPINE (privilege-escalation gate). SECURITY DEFINER bypasses RLS, so this
  -- explicit owner-check IS the access boundary and MUST precede any insert.
  if not public.is_estate_owner(p_estate_id) then
    raise exception 'not estate owner' using errcode = '42501';
  end if;

  -- Q1: no grants to owners (self, or any ownership-role member) — inherent access.
  if p_grantee_user_id = v_user
     or exists (
       select 1 from public.estate_memberships m
       where m.estate_id = p_estate_id
         and m.user_id = p_grantee_user_id
         and public.is_ownership_role(m.role)
     ) then
    raise exception 'cannot grant access to an owner; owners have inherent access';
      -- default sqlstate P0001 -> PostgREST 400 (validation)
  end if;

  -- The document must belong to this estate. Prevents inert cross-estate junk rows
  -- (a grant whose estate_id never matches the doc's real estate at read) and turns a
  -- missing/foreign doc into a clean error instead of a confusing ceiling-on-NULL from
  -- the trigger.
  if not exists (
    select 1 from public.documents d
    where d.id = p_document_id and d.estate_id = p_estate_id
  ) then
    raise exception 'document not found in this estate';  -- P0001 -> 400
  end if;

  -- ★ WRITE-TIME RELEASE VOCABULARY (Phase 11-B). The deprecated fused
  --   `after_verified_death_or_incapacity` stays legal in the table CHECK so stored rows remain
  --   readable and unreinterpreted; this gate is what stops a NEW row from carrying the ambiguity.
  --   `after_verified_death` and `after_verified_incapacity` are now expressible and satisfied by
  --   nothing — a widening of what an owner may SAY, never of what a grantee may SEE.
  if not public.release_condition_writable(p_release_condition) then
    raise exception 'unsupported release condition: %', p_release_condition;  -- P0001 -> 400
  end if;

  -- Insert. The ceiling trigger + table CHECKs + unique indexes fire here regardless of
  -- the DEFINER context. Catch the one-active-grant unique violation and surface a
  -- readable error instead of a raw constraint failure (Q4: fail, never silent upsert).
  begin
    insert into public.access_grants
      (estate_id, grantee_user_id, grantee_role, professional_type,
       document_id, category, visibility_tier, release_condition,
       requires_step_up, granted_by_user_id)
    values
      (p_estate_id, p_grantee_user_id, p_grantee_role, p_professional_type,
       p_document_id, null, p_visibility_tier, p_release_condition,
       p_requires_step_up, v_user)
    returning id into v_id;
  exception
    when unique_violation then
      raise exception
        'an active grant already exists for this document and grantee; revoke it first'
        using errcode = '23505';   -- unique_violation -> PostgREST 409 Conflict
  end;

  perform public.write_audit(
    'access_grant.created',
    'access_grants',
    v_id,
    p_estate_id,
    jsonb_build_object(
      'grantee_user_id', p_grantee_user_id,
      'grantee_role', p_grantee_role,
      'document_id', p_document_id,
      'visibility_tier', p_visibility_tier,
      'release_condition', p_release_condition
    )
  );

  -- ★ PHASE 10-E — the GRANTEE learns they have access, but ONLY if they actually do, right now.
  --
  -- A document grant created with `after_owner_approval` confers nothing until it is approved, so
  -- this emits SILENCE for it; `approve_document_grant` is where that person is told. A
  -- death-conditioned or claim-conditioned grant emits silence permanently — nothing here may
  -- announce a release Phase 11 has not built.
  --
  -- The gate reads the STORED row rather than the parameters, because `status` and `approved_at` are
  -- column defaults that this insert never names.
  if exists (
    select 1 from public.access_grants g
    where g.id = v_id
      and public.notification_grant_is_live(g.status, g.release_condition, g.approved_at)
  ) then
    perform public.emit_lifecycle_notification(
      p_grantee_user_id,
      p_estate_id,
      'access_grant.created',
      public.notification_estate_home(p_estate_id, p_grantee_user_id)
    );
  end if;

  return query select g.* from public.access_grants g where g.id = v_id;
end;
$function$;


-- ==== db/functions/approve_document_grant.sql =====================================================
-- public.approve_document_grant(p_grant_id uuid) -> SETOF public.access_grants
--
-- Owner-gated approval of an access grant — sets approved_at + approved_by_user_id
-- atomically and writes an access_grant.approved audit event. Activates
-- after_owner_approval grants: can_access_document passes them once approved_at is set
-- (see db/migrations/0003). Idempotent: approving an already-approved grant returns it
-- unchanged with no duplicate audit.
--
-- THE GENERIC GRANT-APPROVAL PRIMITIVE (docs/live-data-migration.md Appendix A.4) — reused
-- by the later access-request flow + V2 co-owner approval; it does NOT itself implement
-- access requests. Generic by design: it approves ANY active grant; can_access_document
-- currently consults approved_at only for after_owner_approval (approving a grant whose
-- condition doesn't read it is a harmless no-op on visibility).
--
-- SECURITY (load-bearing): SECURITY DEFINER bypasses RLS; the grant's estate is resolved by
-- a read-only lookup, then the explicit is_estate_owner check gates the UPDATE. No mutation
-- before the owner-check. The enforce_grant_ceiling trigger (BEFORE INSERT OR UPDATE, no
-- column guard) RE-FIRES on the approve UPDATE and re-reads the document's CURRENT
-- sensitivity — approval cannot bypass the ceiling (a now-sealed doc -> 42501).
--
-- UUID-case: p_grant_id is uuid-typed — canonicalized automatically.
--
-- Error codes (SQLSTATE -> PostgREST HTTP status):
--   42501 -> 403  unauthenticated / not_estate_owner (privilege gate) / ceiling violation
--                 (from the enforce_grant_ceiling trigger on a now-over-ceiling doc)
--   P0001 -> 400  grant_not_found (default RAISE sqlstate)
--
-- SECURITY DEFINER; relies on auth.uid(). Source of truth — re-apply on DB reset.

create or replace function public.approve_document_grant(p_grant_id uuid)
 returns setof public.access_grants
 language plpgsql
 security definer
 set search_path to 'public', 'extensions'
as $function$
declare
  v_user uuid := auth.uid();
  v_estate uuid;
  v_approved timestamptz;
begin
  if v_user is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  -- Read-only lookup to resolve the grant's estate for the owner-check. No mutation yet.
  select estate_id, approved_at into v_estate, v_approved
  from public.access_grants
  where id = p_grant_id;

  if v_estate is null then
    raise exception 'grant_not_found';  -- P0001 -> 400
  end if;

  -- SECURITY SPINE (privilege-escalation gate): must precede the UPDATE.
  if not public.is_estate_owner(v_estate) then
    raise exception 'not estate owner' using errcode = '42501';
  end if;

  -- Idempotent: already approved -> return as-is, no duplicate audit.
  if v_approved is not null then
    return query select g.* from public.access_grants g where g.id = p_grant_id;
    return;
  end if;

  -- The enforce_grant_ceiling trigger re-fires on this UPDATE and re-reads the document's
  -- CURRENT sensitivity; a doc reclassified above the grantee's ceiling raises 42501 here,
  -- so approval cannot become a ceiling bypass.
  update public.access_grants
     set approved_at = now(),
         approved_by_user_id = v_user,
         updated_at = now()
   where id = p_grant_id;

  perform public.write_audit(
    'access_grant.approved',
    'access_grants',
    p_grant_id,
    v_estate,
    jsonb_build_object('approved_by_user_id', v_user)
  );

  -- ★ PHASE 10-E — approval is the moment an approval-conditioned grant becomes real, so this is
  -- where its grantee is told. Emitted after the UPDATE and after the idempotent early-return, so
  -- re-approving an already-approved grant says nothing a second time.
  --
  -- Still gated: the ceiling trigger re-fires on the UPDATE above and can leave the grant
  -- unusable, and a death- or claim-conditioned grant is not made live merely by being approved.
  -- The gate asks the row what it now IS rather than assuming approval means released.
  if exists (
    select 1 from public.access_grants g
    where g.id = p_grant_id
      and public.notification_grant_is_live(g.status, g.release_condition, g.approved_at)
  ) then
    perform public.emit_lifecycle_notification(
      (select g.grantee_user_id from public.access_grants g where g.id = p_grant_id),
      v_estate,
      'access_grant.created',
      public.notification_estate_home(
        v_estate,
        (select g.grantee_user_id from public.access_grants g where g.id = p_grant_id)
      )
    );
  end if;

  return query select g.* from public.access_grants g where g.id = p_grant_id;
end;
$function$;


-- ==== db/functions/revoke_document_grant.sql ======================================================
-- public.revoke_document_grant(p_grant_id uuid) -> SETOF public.access_grants
--
-- Audited, single-entry interface for revoking an access grant
-- (docs/live-data-migration.md Appendix A.2). Sets status='revoked',
-- revoked_at=now(), revoked_by_user_id=auth.uid() atomically and writes an
-- access_grant.revoked audit event. Idempotent: revoking an already-revoked grant
-- returns it unchanged with no duplicate audit. The direct PATCH-to-status path
-- (RLS access_grants_update) stays valid during transition (curl ⑦).
--
-- SECURITY (load-bearing): SECURITY DEFINER bypasses RLS. The grant's estate is
-- resolved by a read-only lookup (required — the owner-check needs the estate), then
-- the explicit is_estate_owner check gates the UPDATE. No mutation occurs before the
-- owner-check.
--
-- The enforce_grant_ceiling trigger does NOT block revoke: it only enforces when the
-- resulting row is status='active', so a sealed-reclassified doc can still be revoked.
--
-- UUID-case: p_grant_id is uuid-typed — canonicalized automatically; no manual cast.
--
-- Error codes (SQLSTATE -> PostgREST HTTP status; only mapped SQLSTATEs avoid 500):
--   42501 -> 403  unauthenticated (no auth.uid) / not_estate_owner (the privilege gate)
--   P0001 -> 400  grant_not_found (default RAISE sqlstate; message distinguishes)
--
-- SECURITY DEFINER; relies on auth.uid(). Source of truth — re-apply on DB reset.

create or replace function public.revoke_document_grant(p_grant_id uuid)
 returns setof public.access_grants
 language plpgsql
 security definer
 set search_path to 'public', 'extensions'
as $function$
declare
  v_user uuid := auth.uid();
  v_estate uuid;
  v_status text;
begin
  -- Auth null-guard.
  if v_user is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  -- Read-only lookup to resolve the grant's estate for the owner-check. No mutation
  -- happens before the gate below.
  select estate_id, status into v_estate, v_status
  from public.access_grants
  where id = p_grant_id;

  if v_estate is null then
    raise exception 'grant_not_found';  -- P0001 -> 400
  end if;

  -- SECURITY SPINE (privilege-escalation gate): must precede the UPDATE.
  if not public.is_estate_owner(v_estate) then
    raise exception 'not estate owner' using errcode = '42501';
  end if;

  -- Idempotent: already revoked -> return as-is, no duplicate audit.
  if v_status = 'revoked' then
    return query select g.* from public.access_grants g where g.id = p_grant_id;
    return;
  end if;

  update public.access_grants
     set status = 'revoked',
         revoked_at = now(),
         revoked_by_user_id = v_user,
         updated_at = now()
   where id = p_grant_id;

  perform public.write_audit(
    'access_grant.revoked',
    'access_grants',
    p_grant_id,
    v_estate,
    jsonb_build_object('revoked_by_user_id', v_user)
  );

  -- ★ PHASE 10-E — the GRANTEE learns their access changed, and learns NOTHING ELSE.
  --
  -- The copy is "Your access to shared estate information has changed." It does not name the
  -- document, the category, the tier, or who revoked it. That is the point: whatever was authorized
  -- a moment ago is not authorized now, and a notification row OUTLIVES the grant it describes — so
  -- "Your access to 2026 UBS Account Statement was revoked" would re-disclose that title forever, in
  -- the one place the person can still read it after losing the right to.
  --
  -- Emitted after the UPDATE and after the idempotent early-return above, so a second revoke of an
  -- already-revoked grant says nothing a second time.
  perform public.emit_lifecycle_notification(
    (select g.grantee_user_id from public.access_grants g where g.id = p_grant_id),
    v_estate,
    'access_grant.revoked',
    null   -- nothing to open; a link here would lead to a refusal
  );

  return query select g.* from public.access_grants g where g.id = p_grant_id;
end;
$function$;


-- ==== db/functions/provision_from_invitation.sql ==================================================
-- public.provision_from_invitation(p_invitation_id uuid, p_user uuid) -> uuid (estate_memberships.id)
--
-- SHARED, idempotent post-status provisioning for BOTH accept_invitation and bind_invitation_token (0021).
-- Holds: membership-reconcile + beneficiary self-link (triple-equality) + executor/trustee designation stamp
-- + audit. Assumes the caller already locked the invitation FOR UPDATE and ran the status + P0006 identity
-- guards. INTERNAL only (revoked from public/anon/authenticated — the DEFINER callers invoke it as owner).
--
-- Why a shared helper: a bind-accepted executor must NEVER end up membership-without-designation (a silent
-- authority void). Centralizing here also fixes the pre-existing bind beneficiary-self-link asymmetry.
-- Idempotent: membership ON CONFLICT(estate_id,user_id) DO NOTHING (reuse, don't duplicate); designation
-- ON CONFLICT (partial-unique-on-active) DO NOTHING; designation.created audited ONLY when inserted.
-- Captured from live 2026-07-15 (migration 0021). Source of truth — re-apply on reset.

create or replace function public.provision_from_invitation(p_invitation_id uuid, p_user uuid)
 returns uuid
 language plpgsql
 security definer
 set search_path to 'public', 'extensions'
as $function$
declare
  v_inv record;
  v_membership_id uuid;
  v_desig_id uuid;
begin
  select * into v_inv from public.invitations where id = p_invitation_id;
  if not found then raise exception 'invitation_not_found' using errcode = 'P0002'; end if;

  insert into public.estate_memberships
    (id, estate_id, user_id, role, status, source_invitation_id, approved_at, created_at)
  values
    (gen_random_uuid(), v_inv.estate_id, p_user, v_inv.proposed_role, 'approved', v_inv.id, now(), now())
  on conflict (estate_id, user_id) do nothing
  returning id into v_membership_id;
  if v_membership_id is null then
    select em.id into v_membership_id from public.estate_memberships em
     where em.estate_id = v_inv.estate_id and em.user_id = p_user;
  end if;

  if v_inv.proposed_role::text = 'beneficiary' then
    update public.beneficiaries set user_id = p_user
     where estate_id = v_inv.estate_id and user_id is null
       and ((v_inv.invitee_email is not null and lower(email) = lower(v_inv.invitee_email))
            or (v_inv.invitee_phone is not null and phone = v_inv.invitee_phone));
  end if;

  if v_inv.kind in ('executor','trustee') then
    v_desig_id := null;
    insert into public.estate_designations
      (estate_id, user_id, designation_type, status, source_invitation_id, granted_by)
    values (v_inv.estate_id, p_user, v_inv.kind, 'active', v_inv.id, v_inv.invited_by)
    on conflict (estate_id, user_id, designation_type) where status = 'active' do nothing
    returning id into v_desig_id;
    if v_desig_id is not null then
      perform public.write_audit('designation.created', 'estate_designations', v_desig_id, v_inv.estate_id,
        jsonb_build_object('invitation_id', v_inv.id, 'designation_type', v_inv.kind));
    end if;
    -- VERIFICATION HOOK (NO-OP): per-claim verification (Reading A) attaches here later; no external call.
  end if;

  return v_membership_id;
end;
$function$;
revoke execute on function public.provision_from_invitation(uuid, uuid) from public, anon, authenticated;


-- ==== db/functions/accept_invitation.sql ==========================================================
-- public.accept_invitation(p_invitation_id uuid)
--   -> TABLE(membership_id uuid, estate_id uuid, estate_display_name text, role text, status text)
--
-- Accepts an invitation BY ID (matched-invitations screen). Validates token/expiry/status + the P0006
-- identity guard (caller's own contact must match the invitee), then delegates provisioning to the shared
-- public.provision_from_invitation helper (membership-reconcile + beneficiary self-link + executor/trustee
-- designation + audit). Idempotent: re-accept returns the existing membership and self-heals via the helper.
--
-- Error codes: 42501 unauthenticated, P0002 not_found, P0003 expired, P0004 revoked, P0005 already_accepted
-- (by someone else), P0006 not_for_caller, P0007 declined.
--
-- Captured from live 2026-07-15 (migration 0021 — refactored onto the shared helper). SECURITY DEFINER.

create or replace function public.accept_invitation(p_invitation_id uuid)
 returns table(membership_id uuid, estate_id uuid, estate_display_name text, role text, status text)
 language plpgsql
 security definer
 set search_path to 'public', 'extensions'
as $function$
declare
  v_user uuid := auth.uid();
  v_inv record; v_user_email text; v_user_phone text; v_membership_id uuid;
begin
  if v_user is null then raise exception 'unauthenticated' using errcode = '42501'; end if;
  select * into v_inv from public.invitations where id = p_invitation_id for update;
  if not found then raise exception 'invitation_not_found' using errcode = 'P0002'; end if;
  if v_inv.expires_at < now() then raise exception 'invitation_expired' using errcode = 'P0003'; end if;
  if v_inv.status = 'revoked' then raise exception 'invitation_revoked' using errcode = 'P0004'; end if;
  if v_inv.status = 'declined' then raise exception 'invitation_declined' using errcode = 'P0007'; end if;

  select profiles.email, profiles.phone into v_user_email, v_user_phone from public.profiles where profiles.id = v_user;
  if not ((v_inv.invitee_email is not null and lower(v_inv.invitee_email) = lower(coalesce(v_user_email,'')))
       or (v_inv.invitee_phone is not null and v_inv.invitee_phone = coalesce(v_user_phone,''))) then
    raise exception 'invitation_not_for_caller' using errcode = 'P0006';
  end if;

  -- Idempotency keys on the invitation's OWN accepted_by (authoritative), NOT the membership's
  -- source_invitation_id: a reconciled membership (an executor who was already a beneficiary member) has a
  -- different/NULL source, so keying on source would (a) spuriously P0005 a same-user re-accept AND (b)
  -- NEVER self-heal a missing designation — the silent-authority-void the shared helper exists to prevent.
  if v_inv.status = 'accepted' then
    if v_inv.accepted_by = v_user then
      perform public.provision_from_invitation(v_inv.id, v_user);   -- idempotent self-heal (re-stamps a missing designation)
      select em.id into v_membership_id from public.estate_memberships em
       where em.estate_id = v_inv.estate_id and em.user_id = v_user;
      return query select v_membership_id, v_inv.estate_id,
        (select e.name from public.estates e where e.id = v_inv.estate_id), v_inv.proposed_role::text, 'approved'::text;
      return;
    else
      raise exception 'invitation_already_accepted' using errcode = 'P0005';
    end if;
  end if;

  update public.invitations set status='accepted', accepted_by=v_user, accepted_at=now(), updated_at=now() where id=v_inv.id;
  v_membership_id := public.provision_from_invitation(v_inv.id, v_user);
  perform public.write_audit('invitation.accepted', 'estate_memberships', v_membership_id, v_inv.estate_id,
    jsonb_build_object('invitation_id', v_inv.id, 'via', 'accept_by_id'));

  -- ★ PHASE 10-E — the OWNER learns their invitation was accepted. Deliberately BELOW the idempotent
  -- re-accept branch above, which returns early: a self-heal re-accept must not tell the owner a
  -- second time that someone joined.
  --
  -- The copy says "someone you invited", never who. The owner issued the invitation and already
  -- knows the invitee, so this says strictly LESS than they know — which is the correct direction
  -- for a surface whose whole job is to avoid becoming a disclosure channel. It also never names the
  -- accepted ROLE: a membership role is a relationship, and relationships are stated by the
  -- authoritative surfaces that already gate them, not by a heads-up.
  perform public.emit_lifecycle_notification(
    public.estate_owner_user_id(v_inv.estate_id),
    v_inv.estate_id,
    'invitation.accepted',
    'afterworth://owner-invitations'
  );
  return query select v_membership_id, v_inv.estate_id,
    (select e.name from public.estates e where e.id = v_inv.estate_id), v_inv.proposed_role::text, 'approved'::text;
end;
$function$;


-- ==== db/functions/decline_invitation.sql =========================================================
-- public.decline_invitation(p_invitation_id uuid) -> void
--
-- Declines an invitation BY ID. Used by the in-app "matched invitations" screen.
-- Same invitee email/phone guard as accept_invitation. Sets status='declined'.
-- Does NOT create a membership.
--
-- Semantics:
--   - pending / matched -> declined (the normal case)
--   - already declined   -> no-op, returns successfully (idempotent)
--   - accepted           -> error P0005 (cannot decline what you've accepted;
--                           removing a membership is a separate operation)
--   - revoked / expired  -> P0004 / P0003 (nothing to decline)
--
-- Error codes (mapped in api/invitations/decline.ts):
--   42501 unauthenticated, P0002 not_found, P0003 expired, P0004 revoked,
--   P0005 already_accepted, P0006 not_for_caller.
--
-- SECURITY DEFINER; relies on auth.uid(). Source of truth — re-apply on DB reset.

CREATE OR REPLACE FUNCTION public.decline_invitation(p_invitation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_user uuid := auth.uid();
  v_inv record;
  v_user_email text;
  v_user_phone text;
begin
  if v_user is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  select * into v_inv
  from public.invitations
  where id = p_invitation_id
  for update;

  if not found then
    raise exception 'invitation_not_found' using errcode = 'P0002';
  end if;

  -- Verify the caller is the intended invitee (same guard as accept).
  select profiles.email, profiles.phone into v_user_email, v_user_phone
  from public.profiles
  where profiles.id = v_user;

  if not (
    (v_inv.invitee_email is not null
     and lower(v_inv.invitee_email) = lower(coalesce(v_user_email, '')))
    or
    (v_inv.invitee_phone is not null
     and v_inv.invitee_phone = coalesce(v_user_phone, ''))
  ) then
    raise exception 'invitation_not_for_caller' using errcode = 'P0006';
  end if;

  -- Idempotent: already declined is a successful no-op.
  if v_inv.status = 'declined' then
    return;
  end if;

  if v_inv.status = 'accepted' then
    raise exception 'invitation_already_accepted' using errcode = 'P0005';
  end if;

  if v_inv.status = 'revoked' then
    raise exception 'invitation_revoked' using errcode = 'P0004';
  end if;

  if v_inv.expires_at < now() then
    raise exception 'invitation_expired' using errcode = 'P0003';
  end if;

  update public.invitations
     set status = 'declined',
         updated_at = now()
   where id = v_inv.id;

  perform public.write_audit(
    'invitation.declined',
    'invitations',
    v_inv.id,
    v_inv.estate_id,
    jsonb_build_object('invitation_id', v_inv.id)
  );

  -- ★ PHASE 10-E — the OWNER learns an invitation was declined. Below the idempotent
  -- already-declined early-return, so a repeat decline emits nothing the second time. That
  -- placement is load-bearing and is asserted: an emitter moved above the idempotency guard would
  -- produce one notification per call rather than one per event, and nothing else would notice.
  --
  -- No deep link on this one — the invitation is finished, and there is no state to go and look at.
  perform public.emit_lifecycle_notification(
    public.estate_owner_user_id(v_inv.estate_id),
    v_inv.estate_id,
    'invitation.declined',
    null
  );
end;
$function$;

commit;
-- ★ If you see an error above and no COMMIT, nothing was applied. Fix the cause and paste again.
